/*
 * World land outline for the panda map, projected with d3-geo's Natural Earth projection and fitted
 * to longitudes -170 to 180 and latitudes -50 to 78 (Antarctica left out). Generated once from
 * world-atlas 2.0.2 countries-110m (Natural Earth, public domain) with d3-geo 3.1.1 and
 * topojson-client 3.1.0; regenerate the same way if the frame changes. Self-hosted so the website
 * and the app draw the same outline and request no third-party tiles.
 */

export const WORLD_WIDTH = 1000;
export const WORLD_HEIGHT = 470;

const SCALE = 182.8234;
const TRANSLATE_X = 500;
const TRANSLATE_Y = 274.5332;

/** The Natural Earth projection of one point, in the outline's coordinate space. */
export function projectToWorld(longitude: number, latitude: number): { x: number; y: number } {
  const lambda = (longitude * Math.PI) / 180;
  const phi = (latitude * Math.PI) / 180;
  const phi2 = phi * phi;
  const phi4 = phi2 * phi2;
  const x = lambda * (0.8707 - 0.131979 * phi2 + phi4 * (-0.013791 + phi4 * (0.003971 * phi2 - 0.001529 * phi4)));
  const y = phi * (1.007226 + phi2 * (0.015085 + phi4 * (-0.044475 + 0.028874 * phi2 - 0.005916 * phi4)));
  return { x: TRANSLATE_X + SCALE * x, y: TRANSLATE_Y - SCALE * y };
}

